SourceCode.Declaration:
/// <summary>
/// The TFMDocLocalization is the document handler for overriding translations on the mobile device.
/// </summary>
class TFMDocLocalization extends TFMDocumentHandler
{
}

Method.Source:
/// <summary>
///
/// </summary>
/// <returns></returns>
public TFMDocumentHandlerDescription description()
{
    TFMDocumentHandlerDescription ret;

    ret = "@TFM:TranslationService";
    return ret;
}

/// <summary>
///
/// </summary>

private void addTranslationToXml(TFMDocumentNodes _nodes, TFMDocumentNode _parent, str _name, str _value)
{
    TFMDocumentNode     translation;
    translation = _nodes.makeChild(_parent,'string');
    translation.addAttribute('name',_name);
    translation.parmValue(_value);
}

public void process()
{
    TFMDocumentNodes    nodes               = TFMDocumentNodes::Construct('localization');
    TFMDocumentNode     localization        = nodes.getRoot();
    TFMDocumentNode     langNode            = nodes.makeChild(localization,'language');
    Map                 translationMap      = TFMTranslationProvider::getAllTranslationsForCurrentUserLanguage();
    MapEnumerator       mEnum;

    langNode.addAttribute('code', TFMDocLocalization::getUserLanguage());

    mEnum = translationMap.getEnumerator();
    while (mEnum.moveNext())
    {
        this.addTranslationToXml(nodes,langNode,mEnum.currentKey(),mEnum.currentValue());
    }
    langNode.addAttribute('version', this.UserLanguageCustomizationVersion());
    resultXml = nodes.makeXml();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public Set getDocumentTypes()
{
    Set ret = new Set(Types::String);
    ret.add(methodStr(TFMDocLocalization,GetLocalizationData));

    return ret;
}

public Set getReferenceDataMethods()
{
    Set ret = new Set(Types::String);

    ret.add(methodStr(TFMDocLocalization, UserLanguageCustomizationVersion));

    return ret;
}

/// <summary>
/// Method to provide the newest version of language customizations.
/// </summary>
/// <returns>The current version as a string</returns>
public XML UserLanguageCustomizationVersion()
{
    return 'version.' + TFMDocLocalization::getUserLanguage() + '.' + TFMTranslationProvider::instance().version() + '.' + int2Str(TFMTranslationProvider::getAllTranslationsForCurrentUserLanguage().elements());
}

