public static str getUserLanguage()
{
    UserInfo    userInfo;
    str         language;

    select firstonly userInfo
        where UserInfo.id == curUserId();

    language = strUpr(strLTrim(userInfo.language));

    // We have support for Dutch Belgian (Flemish)
    if (language == 'NL-BE')
    {
        return language;
    }

    // Norway Bokmål does not follow the other iso language codes
    if (language == 'NB-NO')
    {
        return 'NO';
    }

    // 'Always' just use the first two chars in the langauge code.
    if(strLen(language) > 1)
    {
        return subStr(language, 0, 2);
    }

    // if no language then default to english
    return 'EN';
}
